'use strict'

import soundManager from '../service/sound-manager'
import clock from '../service/clock'
import hitboxManager from '../service/hitbox-manager'
import resource from '../resource'
import { UNIQUE_ITEMS, LINK_ACTION_MOVE, SOUND_FANFARE, LINK_ACTION_PICK, SOUND_TEXT_LOOP, SOUND_OVERWORLD, DIRECTION_EAST, DIRECTION_WEST, TRANSITION_MAP_HORIZONTAL_STEP, TRANSITION_MAP_HORIZONTAL_INTERVAL, TRANSITION_MAP_VERTICAL_STEP, TRANSITION_MAP_VERTICAL_INTERVAL, DIRECTION_SOUTH, SOUND_STAIRS, SOUND_LINK_DIE, TILE_WIDTH, TILE_HEIGHT, DIRECTION_NORTH } from '../constant'

class CaveEntrance {
  async play (link) {
    return new Promise((resolve) => {
      link.y += TILE_HEIGHT
      const limitY = link.y - 3 * TILE_HEIGHT
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y -= 2
        if (link.y <= limitY) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

class CaveExit {
  async play (link, currentMap) {
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y += 2
        if (link.y > currentMap.y + currentMap.height) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

// How far from the stairs Link may still be when he goes down them: his center entering the tile is not
// enough (walking sideways along the wall below a cave door, half of him overlaps the door)
const STAIRS_ALIGNMENT_TOLERANCE = TILE_WIDTH / 4

class CaveStairsDown {
  canStart (link, tile) {
    return Math.abs(link.x - tile.x) <= STAIRS_ALIGNMENT_TOLERANCE && Math.abs(link.y - tile.y) <= STAIRS_ALIGNMENT_TOLERANCE
  }

  async play (link) {
    return new Promise((resolve) => {
      soundManager.stop(resource.getSound(SOUND_OVERWORLD))
      soundManager.play(resource.getSound(SOUND_STAIRS))
      link.direction = DIRECTION_NORTH
      const tile = link.tile
      link.clipY = 0
      link.startWalking()
      const transitionTimer = clock.repeat(() => {
        // Link slides onto the stairs while he goes down instead of jumping onto them
        link.x += Math.sign(tile.x - link.x)
        link.y += Math.sign(tile.y - link.y)
        link.clipY++
        if (link.clipY >= TILE_HEIGHT) {
          transitionTimer.cancel()
          link.clipY = 0
          link.stopWalking()
          resolve()
        }
      }, 30)
    })
  }
}

class CaveStairsUp {
  async play (link) {
    return new Promise((resolve) => {
      soundManager.play(resource.getSound(SOUND_STAIRS))
      link.direction = DIRECTION_SOUTH
      link.clipY = TILE_HEIGHT
      link.startWalking()
      const transitionTimer = clock.repeat(() => {
        link.clipY--
        if (link.clipY <= 0) {
          transitionTimer.cancel()
          link.clipY = 0
          link.stopWalking()
          soundManager.play(resource.getSound(SOUND_OVERWORLD))
          resolve()
        }
      }, 30)
    })
  }
}

// Direction in which Link crosses to the next screen
const MAP_DRAG_VECTORS = {
  [DIRECTION_EAST]: [1, 0],
  [DIRECTION_NORTH]: [0, -1],
  [DIRECTION_SOUTH]: [0, 1],
  [DIRECTION_WEST]: [-1, 0]
}

class MapDrag {
  // Both maps scroll by exactly one screen while Link walks from the edge he leaves to the opposite
  // edge of the next screen. The last step is left on display (maps scrolled, Link in the coordinates of
  // the screen he leaves): until the game switches maps, the frames drawn show the next screen in
  // place, and the game resets the offsets when it switches (see Game.process)
  async play (link, currentMap, targetMap) {
    const [dx, dy] = MAP_DRAG_VECTORS[link.direction]
    const horizontal = dx !== 0
    const sign = dx + dy
    const distance = horizontal ? currentMap.width : currentMap.height
    const linkSize = horizontal ? link.width : link.height
    const linkFrom = sign > 0 ? distance - linkSize : 0
    const linkTo = distance - linkSize - linkFrom
    const step = horizontal ? TRANSITION_MAP_HORIZONTAL_STEP : TRANSITION_MAP_VERTICAL_STEP
    const interval = horizontal ? TRANSITION_MAP_HORIZONTAL_INTERVAL : TRANSITION_MAP_VERTICAL_INTERVAL
    const nbTicks = Math.round(distance / step)

    let tick = 0
    const update = () => {
      const progress = tick / nbTicks
      const offset = -sign * distance * progress
      const linkPosition = linkFrom + (linkTo - linkFrom) * progress
      if (horizontal) {
        currentMap.offsetX = offset
        targetMap.offsetX = offset
        link.x = currentMap.x + linkPosition
      } else {
        currentMap.offsetY = offset
        targetMap.offsetY = offset
        link.y = currentMap.y + linkPosition
      }
    }

    update()
    link.startWalking()
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        tick++
        update()
        if (tick >= nbTicks) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, interval)
    })
  }
}

class ItemPick {
  buy (link, item) {
    let i = item.price ?? 0
    const soundTimer = clock.repeat(() => {
      // soundManager.play(resource.getSound(SOUND_GET_RUPEE))
    }, 200)
    const buyTimer = clock.repeat(() => {
      i--
      link.inventory.rupees--
      if (i === 0) {
        buyTimer.cancel()
        soundTimer.cancel()
        if (link.inventory.rupees < 0) {
          link.inventory.rupees = 0
        }
      }
    }, 25)
  }

  removeItemFromMap (map, item) {
    const index = map.items.indexOf(item)
    if (index > -1) {
      map.items.splice(index, 1)
    }
  }

  addItemToMap (map, item) {
    map.items.push(item)
  }

  play (link, item) {
    if (item.price) {
      this.buy(link, item)
    }

    if (link.map.character) {
      link.map.character.vanish(1300)
    }

    const clonedItem = item.clone()
    clonedItem.price = undefined
    for (const i of link.map.items) {
      i.enabled = false
    }

    // Test picking item or not
    /* if (false) {
      this.finalizeTransition(link.map, item)
      return
    } */

    link.stopWalking()
    link.action = LINK_ACTION_PICK
    this.addItemToMap(link.map, clonedItem)

    const itemCenterX = hitboxManager.getHorizontalCenter(clonedItem.hitbox)
    const itemDeltaX = itemCenterX - clonedItem.x
    clonedItem.x = link.x - itemDeltaX + 4
    clonedItem.y = link.y - clonedItem.height
    soundManager.play(resource.getSound(SOUND_FANFARE))

    const self = this
    return new Promise((resolve) => {
      clock.delay(() => {
        link.action = LINK_ACTION_MOVE
        self.removeItemFromMap(link.map, clonedItem)
        self.finalizeTransition(link, item)
        resolve()
      }, 1300)
    })
  }

  finalizeTransition (link, item) {
    link.pickItem(item)
    if (UNIQUE_ITEMS.includes(item.name)) {
      link.map.items = []
      link.map.characters = []
    }
  }
}

class Dialog {
  async play (link) {
    let length = 0
    soundManager.play(resource.getSound(SOUND_TEXT_LOOP))
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        length++
        link.map.character.displayedText = link.map.character.text.substring(0, length)
        if (link.map.character.displayedText === link.map.character.text) {
          soundManager.stop(resource.getSound(SOUND_TEXT_LOOP))
          transitionTimer.cancel()
          resolve()
        }
      }, 50)
    })
  }
}

// Death of Link, as in the original game (durations in milliseconds, approximate)
const DEATH_SPIN_ORDER = [DIRECTION_SOUTH, DIRECTION_WEST, DIRECTION_NORTH, DIRECTION_EAST]
const DEATH_SPIN_INTERVAL = 80
const DEATH_SPIN_DURATION = 1600
const DEATH_DARKNESS_STEPS = [0.4, 0.7, 1]
const DEATH_DARKNESS_STEP_DURATION = 200
const DEATH_GREY_DURATION = 600
const DEATH_SPARKLE_FRAME_DURATION = 150
const DEATH_SPARKLE_FRAMES = 3
const DEATH_EMPTY_DURATION = 400
const DEATH_GAME_OVER_DURATION = 2000

function wait (duration) {
  return new Promise((resolve) => clock.delay(resolve, duration))
}

// The screen freezes, the enemies vanish and the music stops. Link spins on a red screen that darkens to
// black, turns grey, becomes a sparkle and vanishes, then GAME OVER. The steps are published in
// game.deathEffect, which Game.draw follows
class Death {
  async play (game) {
    const link = game.link
    soundManager.stop(resource.getSound(SOUND_OVERWORLD))
    soundManager.play(resource.getSound(SOUND_LINK_DIE))
    game.map.clearEnemies()
    link.knockback = undefined
    link.invincibleSteps = 0
    link.usingItem = false
    link.action = LINK_ACTION_MOVE
    link.standStill()

    const effect = { darkness: 0, grey: false, sparkleFrame: undefined, hidden: false, gameOver: false }
    game.deathEffect = effect

    let turn = DEATH_SPIN_ORDER.indexOf(link.direction)
    const spinTimer = clock.repeat(() => {
      turn++
      link.direction = DEATH_SPIN_ORDER[turn % DEATH_SPIN_ORDER.length]
    }, DEATH_SPIN_INTERVAL)
    await wait(DEATH_SPIN_DURATION)
    spinTimer.cancel()
    link.direction = DIRECTION_SOUTH

    for (const darkness of DEATH_DARKNESS_STEPS) {
      effect.darkness = darkness
      await wait(DEATH_DARKNESS_STEP_DURATION)
    }

    effect.grey = true
    await wait(DEATH_GREY_DURATION)

    for (let frame = 0; frame < DEATH_SPARKLE_FRAMES; frame++) {
      effect.sparkleFrame = frame
      await wait(DEATH_SPARKLE_FRAME_DURATION)
    }
    effect.sparkleFrame = undefined
    effect.hidden = true
    await wait(DEATH_EMPTY_DURATION)

    effect.gameOver = true
    await wait(DEATH_GAME_OVER_DURATION)
  }
}

export { CaveEntrance, CaveExit, CaveStairsDown, CaveStairsUp, MapDrag, Dialog, ItemPick, Death }
